import os
import tomllib
from typing import Any


class ConfigError(Exception):
    def __init__(self, key: str, expected: str) -> None:
        self.key = key
        self.expected = expected
        super().__init__(f"{key}: expected {expected}")


def _coerce(value: str, target_type: type) -> Any:
    if target_type is bool:
        return value.lower() in ("true", "1", "yes")
    if target_type is int:
        return int(value)
    if target_type is float:
        return float(value)
    return value  # str


def load_config(
    defaults: dict[str, Any],
    toml_path: str | None = None,
    env_prefix: str = "APP",
    env: dict[str, str] | None = None,
) -> dict[str, Any]:
    config = dict(defaults)
    if toml_path is not None:
        try:
            with open(toml_path, "rb") as f:
                toml = tomllib.load(f)
        except FileNotFoundError:
            pass
        else:
            for k, v in toml.items():
                if isinstance(v, dict):
                    config[k] = config.get(k, {}) | v
                else:
                    config[k] = v
    if env is None:
        env = dict(os.environ)
    prefix = env_prefix.upper()
    for name, value in env.items():
        if not name.startswith(f"{prefix}__"):
            continue
        rest = name[len(prefix) + 2 :]
        keys = rest.split("__")
        key = keys[-1]
        if key not in config:
            raise ConfigError(key, "orphan")
        target_type = type(config[key])
        try:
            coerced = _coerce(value, target_type)
        except ValueError:
            raise ConfigError(key, target_type.__name__)
        config[key] = coerced
    return config

import os
import tempfile
import pytest
from envcfg import load_config, ConfigError


def _env(prefix: str, **kwargs) -> dict[str, str]:
    return {f"{prefix}__{k}": v for k, v in kwargs.items()}


def _toml(path: str, data: dict) -> None:
    with open(path, "w") as f:
        f.write("# dummy\n")
        for k, v in data.items():
            if isinstance(v, dict):
                f.write(f"[{k}]\n")
                for sk, sv in v.items():
                    f.write(f"  {sk} = {sv}\n")
            else:
                f.write(f"{k} = {v}\n")


def test_defaults_only():
    cfg = load_config({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_over_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = f.name
        _toml(path, {"b": 3, "c": 4})
    cfg = load_config({"a": 1, "b": 2}, toml_path=path)
    os.unlink(path)
    assert cfg == {"a": 1, "b": 3, "c": 4}


def test_env_over_defaults():
    cfg = load_config({"a": 1, "b": 2}, env=_env("APP", a="10", b="3"))
    assert cfg == {"a": 10, "b": 3}


def test_env_over_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = f.name
        _toml(path, {"b": 3, "c": 4})
    cfg = load_config({"a": 1}, toml_path=path, env=_env("APP", b="10", c="true"))
    os.unlink(path)
    assert cfg == {"a": 1, "b": 10, "c": True}


def test_nested_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = f.name
        _toml(path, {"server": {"port": 8080, "host": "0.0.0.0"}})
    cfg = load_config({}, toml_path=path)
    os.unlink(path)
    assert cfg == {"server": {"port": 8080, "host": "0.0.0.0"}}


def test_nested_env():
    cfg = load_config(
        {"server": {"port": 80}},
        env=_env("APP", server__port="9000", server__host="127.0.0.1"),
    )
    assert cfg == {"server": {"port": 9000, "host": "127.0.0.1"}}


